import urllib.request
import json

# Try to get monthly CPI-U data
# Let's try different series IDs for monthly data
series_ids = ['CUUR0000SA0', 'CUUR0000SA0L1E', 'CUUR0000SA0L1E']

for sid in series_ids:
    url = 'https://api.bls.gov/publicAPI/v2/timeseries/data/' + sid
    headers = {'Content-type': 'application/json'}
    data = json.dumps({
        'seriesid': [sid],
        'startyear': '1968',
        'endyear': '1970'
    }).encode('utf-8')

    req = urllib.request.Request(url, data=data, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=10) as response:
            result = json.loads(response.read().decode())
            if result.get('status') == 'REQUEST_SUCCEEDED':
                print(f'Series: {sid}')
                for series in result.get('Results', {}).get('series', []):
                    for item in series.get('data', []):
                        if item.get('month'):
                            print(f\"  {item.get('year')}-{item.get('month').zfill(2)}: {item.get('value')}\")
    except Exception as e:
        print(f'Error for {sid}: {e}')
"

